// Generates docs/reference/{hooks,settings,rest-and-blocks}.md from the naming registry and the settings schema.
// Usage: node tools/docs-reference.mjs [--check]   (--check fails when the committed files are out of date)
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fromRoot } from './lib/paths.mjs';

const registry = JSON.parse(readFileSync(fromRoot('docs/spec/naming-registry.json'), 'utf8'));
const schema = JSON.parse(readFileSync(fromRoot('packages/theme-core/schema/settings.schema.json'), 'utf8'));
const NOTE =
  '<!-- Generated by tools/docs-reference.mjs from docs/spec/naming-registry.json and the settings schema. Do not edit. -->\n';

/** Groups hook names by module (`joo/<module>/...`). */
export function hooksByModule(hooks) {
  const groups = {};
  for (const hook of hooks) (groups[hook.split('/')[1]] ??= []).push(hook);
  return groups;
}

export function hooksPage(reg) {
  const groups = hooksByModule(reg.hooks);
  const body = Object.entries(groups)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([module, hooks]) => `## ${module}\n\n${hooks.map((h) => `- \`${h}\``).join('\n')}\n`)
    .join('\n');
  return `${NOTE}\n# Hooks\n\nEvery public hook is named \`joo/<module>/<event>\` and listed in the naming registry (a test fails on an unregistered name). Filters and actions are not told apart here; see the source of the module for the signature.\n\n${body}`;
}

export function settingsPage(sch) {
  const rows = Object.entries(sch.settings).map(([key, s]) => {
    const def = JSON.stringify(s.default);
    return `| \`${key}\` | ${s.type} | \`${def}\` | ${s.group} | ${String(s.description ?? s.title).replace(/\|/g, '/')} |`;
  });
  return `${NOTE}\n# Settings\n\nPrecedence: filter \`joo/settings/value\`, then the value saved in the admin, then the theme manifest, then the default below.\n\n| Key | Type | Default | Group | Description |\n| --- | --- | --- | --- | --- |\n${rows.join('\n')}\n`;
}

export function surfacePage(reg) {
  const list = (title, items) => `## ${title}\n\n${items.map((i) => `- \`${i}\``).join('\n')}\n`;
  return `${NOTE}\n# REST routes, blocks, post types and stored data\n\nREST namespace: \`joo/v1\`.\n\n${[
    list('REST routes', reg.restRoutes),
    list('Blocks', reg.blocks),
    list('Custom elements', reg.customElements),
    list('Post types', reg.postTypes),
    list('Options', reg.options),
    list('Post meta', [...reg.postMeta, ...reg.postMetaInternal]),
    list('Term meta', reg.termMeta),
    list('User meta', reg.userMeta),
  ].join('\n')}`;
}

const files = {
  'docs/reference/hooks.md': hooksPage(registry),
  'docs/reference/settings.md': settingsPage(schema),
  'docs/reference/surface.md': surfacePage(registry),
};

if (import.meta.url === `file://${process.argv[1]}`) {
  const check = process.argv.includes('--check');
  let stale = 0;
  for (const [path, content] of Object.entries(files)) {
    const file = fromRoot(path);
    if (check) {
      if (!existsSync(file) || readFileSync(file, 'utf8') !== content) {
        console.error(`stale: ${path} (run: node tools/docs-reference.mjs)`);
        stale += 1;
      }
    } else writeFileSync(file, content);
  }
  if (check) process.exit(stale ? 1 : 0);
  console.log(`wrote ${Object.keys(files).length} reference pages`);
}
